// fp kernel square root: the cold path of the short schoolbook root (contract: src/fp/kernel.hpp). The entry is
// src/fp/x86_64/sqrt.S (generated by tools/generate_fp_sqrt.py, whose docstring has the grid and the k <= 2 paths and whose
// comments derive the schoolbook root k = 3..54); sqrt k > 54 is the IFMA root sbn3f_sqrt_qv (div_qv.cpp).
// Until 2026-10-17 this file also held the reciprocal square root's core (sbn3f_root_core: the research prototype's ladders,
// experiments/results/fp_roots_2026-10-09); rsqrt is src/fp/x86_64/rsqrt.S now, and sqrt.S calls sbn3f_sqrt_qv directly.
// The TU keeps its flags (-fno-vectorize -fno-slp-vectorize, config/sources.json): sbn3f_sqrt_sb_fix's machine code is the
// one gated before.
#include <immintrin.h>
#include <stdint.h>

// The cold path of sqrt.S's short schoolbook root (.Lsb), at step j's start (pt = 2k - j, b0 = 2k - 2j) with the window
// spilled: RW[p - cg] = ~R at positions cg .. pt + 1 (R in two's complement over them), D_j = 2 S_j at Db[k-j .. k]. R < 0
// (an estimate over the digit): S_j - 1 (R += D_j - 1 at b0, D_j - 2); R >= D_j + 1 at b0 (an earlier digit low): S_j + 1
// (R -= D_j + 1, D_j + 2), never past S_j = B^j - 1 (the window's slack (the omitted products, positions below cg) can
// put R over D_j + 1 there: x near B^e); positions >= cg only; until neither holds. Returns 1 when ovf (step j's estimate
// reached B) and S_j did not move (the digit is B - 1), else 0.
#ifdef FPK_SQ_COUNT
#include <stdio.h>
static long fpk_sq_cnt[3];
__attribute__((destructor)) static void fpk_sq_report() { fprintf(stderr, "sb cold: S-1 %ld S+1 %ld B-1 %ld\n", fpk_sq_cnt[0], fpk_sq_cnt[1], fpk_sq_cnt[2]); }
#define FPK_SQ_CNT(i) (++fpk_sq_cnt[i])
#else
#define FPK_SQ_CNT(i) ((void)0)
#endif
extern "C" uint64_t sbn3f_sqrt_sb_fix(uint64_t *RW, uint64_t *Db, uint64_t k, uint64_t j, uint64_t ovf, int64_t cg) noexcept {
    const int64_t pt = 2 * int64_t(k) - int64_t(j), b0 = pt - int64_t(j), lo = b0 > cg ? b0 : cg, n = pt + 2 - lo;
    const int64_t d0 = lo - b0, dn = int64_t(j) + 1 - d0;               // D_j's limbs in the window: d0 .. j
    uint64_t *R = RW + (lo - cg), *D = Db + (k - j), T[2 * 256];
    for (int64_t i = 0; i < n; ++i) R[i] = ~R[i];
    bool moved = false;
    for (;;) {
        unsigned char c = 0;
        unsigned long long r;
        if (R[n - 1] >> 63) {                                            // R < 0: S_j - 1
            FPK_SQ_CNT(0);
            for (int64_t i = 0; i < n; ++i) { c = _addcarry_u64(c, R[i], i < dn ? D[d0 + i] : 0, &r); R[i] = r; }
            if (d0 == 0) for (int64_t i = 0; i < n && R[i]-- == 0; ++i) {}
            c = _subborrow_u64(0, D[0], 2, &r);
            D[0] = r;
            for (int64_t i = 1; i <= int64_t(j) && c; ++i) { c = _subborrow_u64(c, D[i], 0, &r); D[i] = r; }
            moved = true;
            continue;
        }
        for (int64_t i = 0; i < n; ++i) { c = _subborrow_u64(c, R[i], i < dn ? D[d0 + i] : 0, &r); T[i] = r; }
        if (d0 == 0) for (int64_t i = 0; i < n && T[i]-- == 0; ++i) {}
        if (T[n - 1] >> 63) break;                                       // R <= D_j (+ the limbs below b0)
        bool top = D[j] == 1 && D[0] >= ~uint64_t(1);                    // S_j = B^j - 1 already: R over D_j + 1 only
        for (int64_t i = 1; i < int64_t(j) && top; ++i) top = D[i] == ~uint64_t(0);   // by the window's slack; R =
        if (top) {                                                       // D_j B^b0 + B^b0 - 1, the largest it can be
            for (int64_t i = 0; i < n; ++i) R[i] = d0 + i <= int64_t(j) ? D[d0 + i] : 0;
            for (int64_t p = cg; p < lo; ++p) RW[p - cg] = 0;           // (complemented) B - 1 below b0
            break;
        }
        FPK_SQ_CNT(1);
        for (int64_t i = 0; i < n; ++i) R[i] = T[i];
        c = _addcarry_u64(0, D[0], 2, &r);
        D[0] = r;
        for (int64_t i = 1; i <= int64_t(j) && c; ++i) { c = _addcarry_u64(c, D[i], 0, &r); D[i] = r; }
        moved = true;
    }
    for (int64_t i = 0; i < n; ++i) R[i] = ~R[i];
    if (ovf && !moved) { FPK_SQ_CNT(2); return 1; }
    return 0;
}
